def cell_of(site_index: int) -> tuple[int, int]:
    return (site_index // LX, site_index % LX)


def link_kind(row: int, column: int) -> str:
    """Classify a cover matrix slot (row <- column) as a lattice link."""
    time_a, space_a = cell_of(row)
    time_b, space_b = cell_of(column)
    delta_t = (time_a - time_b) % COVER_T
    delta_x = (space_a - space_b) % LX
    if delta_x == 0 and delta_t == 1:
        return "T+"
    if delta_x == 0 and delta_t == COVER_T - 1:
        return "T-"
    if delta_t == 0 and delta_x == 1:
        return "X+"
    if delta_t == 0 and delta_x == LX - 1:
        return "X-"
    return "OTHER"


def zero_phase(matrix: sp.MatrixBase) -> bool:
    """`zero` for expressions carrying e^{i alpha} factors."""
    return all(
        sp.expand(sp.powsimp(sp.expand(entry))) == 0 for entry in matrix
    )


def sparse_half(matrix: sp.Matrix) -> dict:
    """The half-block as a dict of (row, column, re/im, modulus) -> coefficient.

    Carrier-linearity is CHECKED here, not assumed: a monomial of any degree
    other than one in the 64 moduli raises.
    """
    out: dict = {}
    for i in range(HALF):
        for j in range(HALF):
            entry = sp.expand(matrix[i, j])
            if entry == 0:
                continue
            for part, tag in ((sp.re(entry), 0), (sp.im(entry), 1)):
                part = sp.expand(part)
                if part == 0:
                    continue
                for monomial, coefficient in sp.Poly(part, *VARS).terms():
                    if sum(monomial) != 1:
                        raise AssertionError("half-block is not carrier-linear")
                    out[(i, j, tag, monomial.index(1))] = coefficient
    return out


def sparse_deadlive(matrix: sp.Matrix) -> dict:
    """Only the PSD-relevant slots (H3): dead rows, live columns."""
    keep = sp.zeros(HALF, HALF)
    for k in DEAD:
        for j in LIVE:
            keep[k, j] = matrix[k, j]
    return sparse_half(keep)


def system_on(positions, target: dict, table: dict):
    """The cancellation system restricted to the ACTIVE slots of `positions`.

    Returns (active_positions, matrix, right_hand_side).  A slot absent from
    `table` has an identically zero ++ image; such a slot contributes NO
    equation and NO constraint, and it is exactly the class the primary solve
    dropped silently.  Here the drop is explicit and the dropped count is
    returned by every caller that reports a dimension.
    """
    active = [p for p in positions if p in table]
    keys = sorted(set(target) | {k for p in active for k in table[p]})
    matrix = sp.Matrix(
        [[table[p].get(k, 0) for p in active] for k in keys]
    ) if keys else sp.zeros(0, len(active))
    rhs = sp.Matrix([[-target.get(k, 0)] for k in keys]) if keys else sp.zeros(0, 1)
    return active, matrix, rhs


def solve_on(positions, target: dict, table: dict):
    """Least-support solve of sum_p c_p table[p] = -target.  Exact rref."""
    active, matrix, rhs = system_on(positions, target, table)
    if not active:
        return (not target), None, active, 0
    rank = matrix.rank()
    if rank != matrix.row_join(rhs).rank():
        return False, None, active, rank
    reduced, pivots = matrix.row_join(rhs).rref()
    solution = sp.zeros(len(active), 1)
    for row, pivot in enumerate(pivots):
        if pivot < len(active):
            solution[pivot] = reduced[row, len(active)]
    return True, solution, active, rank


def as_delta(positions, solution) -> sp.Matrix:
    matrix = sp.zeros(SIZE, SIZE)
    for position, coefficient in zip(positions, solution):
        matrix[position[0], position[1]] = sp.I * coefficient
    return matrix


def class_dimension(active: int, rank: int, invisible: int) -> int:
    """The dimension of the SOLUTION SET, not of its visible restriction.

    This is the arithmetic the primary solve got wrong: it printed
    (active - rank) and called it the dimension of the completion class, while
    every INVISIBLE slot is an unconstrained direction of the same class.
    """
    return (active - rank) + invisible


def field_from(profile: dict) -> dict:
    return {
        cell: (profile.get(cell, sp.Integer(0)), sp.Integer(1))
        for cell in CELLS
    }


def flip_profile(profile: dict) -> dict:
    """sigma -> -sigma cell by cell: the recorded shear sign, negated."""
    return {cell: -value for cell, value in profile.items()}


def components(edges, nodes: int) -> int:
    """Connected components, for the graph route to twist removability."""
    parent = list(range(nodes))

    def find(node: int) -> int:
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    return len({find(node) for node in range(nodes)})


