# ---------------------------------------------------------------------------
# the pre-registered branch Boolean, evaluated from MEASURED channels BY NAME
# ---------------------------------------------------------------------------
def branch_verdict(channels: dict, names: dict) -> tuple:
    """Evaluate the panel's pre-registered three-branch Boolean.

    The criteria, as recorded in the campaign file BEFORE this block ran:
      Branch I   fires iff the completion IS frame-removable;
      Branch II  needs Branch I to fail AND the completed pairing to be
                 holonomy-blind AND no connection witness in the ORB channel
                 AND no connection witness in the XFER channel;
      Branch III fires iff a connection-carrying witness exists.

    FAIL CLOSED.  Every named channel must be PRESENT in the measured dict.  The
    primary solve built its Boolean as all(ok for name, ok, _ in CHECKS if name
    in (...)), so a mistyped or deleted name yielded an EMPTY generator, all([])
    is True, and Branch II fired by DEFAULT on no evidence at all.  A missing
    name here returns the MISSING-INPUT verdict, which no gate accepts.  The ORB
    channel, which the primary's Boolean never consulted, is consulted here
    because the pre-registered wording names it.
    """
    def conjunction(keys) -> object:
        if any(key not in channels for key in keys):
            return None
        return all(bool(channels[key]) for key in keys)

    removable = conjunction(names["frame_removable"])
    blind = conjunction(names["holonomy_blind"])
    orb_clean = conjunction(names["orb_no_witness"])
    xfer_clean = conjunction(names["xfer_no_witness"])
    if any(value is None for value in (removable, blind, orb_clean, xfer_clean)):
        return ("MISSING-INPUT", False, False, False, 0)

    witness = (not blind) or (not orb_clean) or (not xfer_clean)
    branch_one = bool(removable)
    branch_three = bool(witness)
    branch_two = (not branch_one) and (not branch_three)
    label = (
        "I" if branch_one and not branch_three
        else "III" if branch_three and not branch_one
        else "II" if branch_two
        else "CONTRADICTORY"
    )
    consulted = sum(len(group) for group in names.values())
    return (label, branch_one, branch_two, branch_three, consulted)


